INSERT INTO task_type_template (type_id, locale, render_target, template_text, spec_version)
VALUES
    ('G7-FUN-002', 'ru-KZ', 'plaintext', 'Функция задана формулой f(x) = 1/(x − {{d}}). Для каких значений x она определена среди чисел {{values}}?', '1.0.0-draft'),
    ('G7-FUN-003', 'ru-KZ', 'plaintext', 'Является ли отношение {{relation}} функцией?', '1.0.0-draft'),
    ('G7-FUN-004', 'ru-KZ', 'plaintext', 'Функция задана формулой f(x) = {{a}}x + ({{b}}). Найдите f({{x}}).', '1.0.0-draft'),
    ('G7-FUN-005', 'ru-KZ', 'plaintext', 'Даны функции f(x) = {{a1}}x + ({{b1}}) и g(x) = {{a2}}x + ({{b2}}). У какой функции график круче (больше абсолютное значение углового коэффициента)? Ответьте кодом f или g.', '1.0.0-draft'),
    ('G7-FUN-006', 'ru-KZ', 'plaintext', 'Функция задана формулой f(x) = {{a}}x + ({{b}}). Найдите скорость изменения функции (угловой коэффициент).', '1.0.0-draft'),
    ('G7-FUN-007', 'ru-KZ', 'plaintext', 'Функция задана формулой f(x) = {{a}}x + ({{b}}). Найдите начальное значение f(0).', '1.0.0-draft'),
    ('G7-FUN-008', 'ru-KZ', 'plaintext', 'Является ли функция {{formula}} линейной?', '1.0.0-draft'),
    ('G7-FUN-009', 'ru-KZ', 'plaintext', 'Найдите угловой коэффициент прямой, проходящей через точки ({{x1}}, {{y1}}) и ({{x2}}, {{y2}}).', '1.0.0-draft'),
    ('G7-FUN-010', 'ru-KZ', 'plaintext', 'Найдите угловой коэффициент прямой, заданной уравнением {{a}}x + {{b}}y = {{c}}.', '1.0.0-draft'),
    ('G7-FUN-011', 'ru-KZ', 'plaintext', 'У прямой угловой коэффициент {{m}} и ордината пересечения с осью y равна {{b}}. Запишите её уравнение в виде y = mx + b.', '1.0.0-draft'),
    ('G7-FUN-012', 'ru-KZ', 'plaintext', 'Запишите уравнение прямой с угловым коэффициентом {{m}}, проходящей через точку ({{x}}, {{y}}), в виде y − ({{y}}) = {{m}}(x − ({{x}})).', '1.0.0-draft')
